from scipy import ndimage

def interior_cells(grid):
    """Boolean mask: nonzero cells whose full 3x3 neighborhood is entirely nonzero."""
    a = np.array(grid)
    m = a != 0
    out = np.zeros_like(m)
    H, W = a.shape
    for i in range(1, H - 1):
        for j in range(1, W - 1):
            out[i, j] = m[i, j] and m[i-1:i+2, j-1:j+2].all()
    return out

def label_components(grid):
    """8-connected component labels of the nonzero cells (0 = background)."""
    a = np.array(grid)
    lab, _ = ndimage.label(a != 0, structure=np.ones((3, 3)))
    return lab

def marker_colors(grid):
    """List of (i, j, color) for every cell whose color is neither 0 nor 1."""
    a = np.array(grid)
    return [(int(i), int(j), int(a[i, j])) for i, j in zip(*np.where((a != 0) & (a != 1)))]

def nearest_marker_color(grid, lab):
    """Per-component color: the marker inside it, else the nearest marker (Euclidean, cell to cell)."""
    marks = marker_colors(grid)
    colors = {}
    for k in range(1, lab.max() + 1):
        own = [m for m in marks if lab[m[0], m[1]] == k]
        if own:
            colors[k] = own[0][2]
        else:
            bd, best = float("inf"), None
            for i, j, c in marks:
                for y, x in zip(*np.where(lab == k)):
                    d = (y - i) ** 2 + (x - j) ** 2
                    if d < bd:
                        bd, best = d, c
            colors[k] = best
    return colors

def color_interiors_by_marker(grid):
    """Recolor each interior cell with its component's marker color (nearest marker if the component has none)."""
    a = np.array(grid)
    lab = label_components(grid)
    colors = nearest_marker_color(grid, lab)
    out = a.copy()
    for i, j in zip(*np.where(interior_cells(grid))):
        out[i, j] = colors[lab[i, j]]
    return out.tolist()
